section.programlisting:
@Capability(namespace = "my.namespace")
public @interface MyCapability {
  @Attribute("attr")
  String value() default "";
}

@MyCapability("foo")
public MyClass {}

@Capability(namespace = "my.namespace")
public @interface MyCapability {
  @Directive("resource")
  String value() default "";
}

@MyCapability("foo")
public MyClass {}
